// --- credd.FKind.c_perm.Getary
// Return array of pointers
inline algo::aryptr<credd::FPerm*> credd::c_perm_Getary(credd::FKind& parent) {
    return algo::aryptr<credd::FPerm*>(parent.c_perm_elems, parent.c_perm_n);
}

// --- credd.FKind.c_perm.N
// Return number of items in the pointer array
inline i64 credd::c_perm_N(const credd::FKind& parent) {
    return parent.c_perm_n;
}

// --- credd.FKind.c_perm.RemoveAll
// Empty the index. (The rows are not deleted)
inline void credd::c_perm_RemoveAll(credd::FKind& parent) {
    for (u64 i = 0; i < parent.c_perm_n; i++) {
        // mark all elements as not-in-array
        parent.c_perm_elems[i]->kind_c_perm_in_ary = false;
    }
    parent.c_perm_n = 0;
}

// --- credd.FKind.c_perm.qFind
// Return reference without bounds checking
inline credd::FPerm& credd::c_perm_qFind(credd::FKind& parent, u64 idx) {
    return *parent.c_perm_elems[idx];
}

// --- credd.FKind.c_perm.InAryQ
// True if row is in any ptrary instance
inline bool credd::kind_c_perm_InAryQ(credd::FPerm& row) {
    return row.kind_c_perm_in_ary;
}

// --- credd.FKind.c_perm.qLast
// Reference to last element without bounds checking
inline credd::FPerm& credd::c_perm_qLast(credd::FKind& parent) {
    return *parent.c_perm_elems[parent.c_perm_n-1];
}

// --- credd.FKind..Init
// Set all fields to initial values.
inline void credd::FKind_Init(credd::FKind& parent) {
    parent.howto = algo::strptr("");
    parent.prefix = algo::strptr("");
    parent.multiline = bool(false);
    parent.c_perm_elems = NULL; // (credd.FKind.c_perm)
    parent.c_perm_n = 0; // (credd.FKind.c_perm)
    parent.c_perm_max = 0; // (credd.FKind.c_perm)
    parent.ind_kind_next = (credd::FKind*)-1; // (credd.FDb.ind_kind) not-in-hash
    parent.ind_kind_hashval = 0; // stored hash value
}

// --- credd.FKind.c_perm_curs.Reset
inline void credd::kind_c_perm_curs_Reset(kind_c_perm_curs &curs, credd::FKind &parent) {
    curs.elems = parent.c_perm_elems;
    curs.n_elems = parent.c_perm_n;
    curs.index = 0;
}

// --- credd.FKind.c_perm_curs.ValidQ
// cursor points to valid item
inline bool credd::kind_c_perm_curs_ValidQ(kind_c_perm_curs &curs) {
    return curs.index < curs.n_elems;
}

// --- credd.FKind.c_perm_curs.Next
// proceed to next item
inline void credd::kind_c_perm_curs_Next(kind_c_perm_curs &curs) {
    curs.index++;
}

// --- credd.FKind.c_perm_curs.Access
// item access
inline credd::FPerm& credd::kind_c_perm_curs_Access(kind_c_perm_curs &curs) {
    return *curs.elems[curs.index];
}

